def value(v):
    if pd.isna(v):return None
    if isinstance(v,(bool,np.bool_)):return "true" if v else "false"
    if isinstance(v,(np.integer,np.floating,np.bool_)):return v.item()
    return v

def number(v):
    return "undefined" if pd.isna(v) else f"{v:.4f}"

def md_table(f,columns):
    lines=["| "+" | ".join(columns)+" |","| "+" | ".join(["---"]*len(columns))+" |"]
    for _,row in f.iterrows():
        vals=[]
        for c in columns:
            v=row[c]
            vals.append("—" if pd.isna(v) else (f"{v:.4g}" if isinstance(v,(float,np.floating)) else str(v)))
        lines.append("| "+" | ".join(vals)+" |")
    return "\n".join(lines)

def html_table(f):
    head="".join("<th>"+html.escape(c)+"</th>" for c in f.columns)
    rows=[]
    for r in f.itertuples(index=False,name=None):
        cells=[]
        for v in r:
            text="—" if pd.isna(v) else (f"{v:.6g}" if isinstance(v,(float,np.floating)) else str(v))
            cells.append("<td>"+html.escape(text)+"</td>")
        rows.append("<tr>"+"".join(cells)+"</tr>")
    return '<div class="scroll" tabindex="0"><table><thead><tr>'+head+"</tr></thead><tbody>"+"".join(rows)+"</tbody></table></div>"

def project_csv(source, destination, columns, predicate):
    """Preserve exact CSV strings and original row/cell identity."""
    with source.open(newline="") as f:
        original=list(csv.DictReader(f))
    selected=[(i,r) for i,r in enumerate(original) if predicate(r)]
    destination.parent.mkdir(exist_ok=True)
    with destination.open("w",newline="") as f:
        w=csv.DictWriter(f,fieldnames=columns,lineterminator="\n");w.writeheader()
        w.writerows({c:r[c] for c in columns} for _,r in selected)
    return {"source_artifact":"tables/"+source.name,"source_sha256":sha(source),"selected_path":"downloads/"+destination.name,"selected_sha256":sha(destination),"columns":columns,"source_row_indices":[i for i,_ in selected],"row_count":len(selected)}

def check_projection(work,projection):
    source=work/projection["source_artifact"];dest=work/projection["selected_path"]
    assert sha(source)==projection["source_sha256"] and sha(dest)==projection["selected_sha256"]
    with source.open(newline="") as f:original=list(csv.DictReader(f))
    with dest.open(newline="") as f:reader=csv.DictReader(f);selected=list(reader);assert reader.fieldnames==projection["columns"]
    assert len(selected)==projection["row_count"]
    for row,index in zip(selected,projection["source_row_indices"]):
        for c in projection["columns"]:assert row[c]==original[index][c],(index,c,row[c],original[index][c])
    return sum(len(projection["columns"]) for _ in selected)

